package smartcampus;
import java.awt.*;import java.sql.*;import java.util.UUID;
public class Pass extends Panel{TextField plate=UI.field("");TextArea out=new TextArea();Pass(Frame f){setLayout(new BorderLayout(8,8));setBackground(UI.BG);add(UI.label("DIGITAL PARKING PASS",22,UI.NAVY),BorderLayout.NORTH);Panel p=new Panel(new FlowLayout());p.add(new Label("Vehicle Plate"));p.add(plate);Button b=UI.button("GENERATE 24-HOUR PASS",UI.PURPLE);p.add(b);add(p,BorderLayout.WEST);out.setEditable(false);add(out,BorderLayout.CENTER);b.addActionListener(e->make());}void make(){try(Connection c=DB.get()){PreparedStatement p=c.prepareStatement("select vehicle_id from vehicles where plate_number=?");p.setString(1,plate.getText());ResultSet r=p.executeQuery();if(!r.next()){out.setText("Vehicle not found");return;}String code="PASS-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();p=c.prepareStatement("insert into parking_passes(vehicle_id,pass_code,valid_from,valid_until,status) values(?,?,now(),date_add(now(),interval 1 day),'Active')");p.setInt(1,r.getInt(1));p.setString(2,code);p.executeUpdate();out.setText("================================\n SMART CAMPUS DIGITAL PASS\n================================\nPass Code : "+code+"\nVehicle   : "+plate.getText()+"\nValidity  : 24 hours\nStatus    : ACTIVE\n================================");}catch(Exception e){out.setText(e.getMessage());}}}
